  CadCoord::LocalFromWorld(st, w2x, w2y, &lx2, &ly2);
  CommitSurfMovePointLocal(st, s, static_cast<double>(lx1), static_cast<double>(ly1), static_cast<double>(lx2),
                           static_cast<double>(ly2), static_cast<float>(w2z), log);
