  ClearPendingViewportZoom(st);
  ResetAllCadDraftTools(st);
  st.selectedSurveyPointIndices.clear();
  st.selBoxWaitingSecond = false;
  st.surfaceElevPhase = SEP::WaitFirst;
  st.surfaceElevFromZ.clear();
